import { Elements } from "./elements.js";
import { findCell } from "./utils.js";
import carrier from "./img/ship-carrier.png";
import battleship from "./img/ship-battleship.png";
import submarine from "./img/ship-submarine.png";
import destroyer from "./img/ship-destroyer.png";
import boat from "./img/ship-boat.png";

export const Render = (function () {
	let lastHoveredCells = [];

	function renderSVGborder(ship) {
		const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
		svg.classList.add("border");
		svg.setAttribute("version", "1.1");
		svg.innerHTML = `
        <defs>
            <filter id="squiggly-0">
              <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="0"/>
              <feDisplacementMap id="displacement" in="SourceGraphic" in2="noise" scale="6" />
            </filter>
            <filter id="squiggly-1">
              <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="1"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="8" />
            </filter>

            <filter id="squiggly-2">
              <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="2"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="6" />
            </filter>
            <filter id="squiggly-3">
              <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="3"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="8" />
            </filter>

            <filter id="squiggly-4">
              <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="4"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="6" />
            </filter>
          </defs>
        `;

		ship.appendChild(svg);
	}

	function renderAxis(axis) {
		const span = document.querySelector("#btn-rotate span");

		switch (axis) {
			case "x":
				span.textContent = "x";
				break;
			case "y":
				span.textContent = "y";
		}
	}

	function renderField(owner) {
		const axisX = document.createElement("div");
		axisX.classList.add("axis-x");
		axisX.innerHTML = `
        <div class="char">A</div>
        <div class="char">B</div>
        <div class="char">C</div>
        <div class="char">D</div>
        <div class="char">E</div>
        <div class="char">F</div>
        <div class="char">G</div>
        <div class="char">H</div>
        <div class="char">I</div>
        <div class="char">J</div>
      `;
		const axisY = document.createElement("div");
		axisY.classList.add("axis-y");
		axisY.innerHTML = `
        <div class="num">1</div>
        <div class="num">2</div>
        <div class="num">3</div>
        <div class="num">4</div>
        <div class="num">5</div>
        <div class="num">6</div>
        <div class="num">7</div>
        <div class="num">8</div>
        <div class="num">9</div>
        <div class="num">10</div>
      `;

		const field = document.createElement("div");

		for (let i = 0; i < 100; i++) {
			const cell = document.createElement("div");
			let row = Math.floor(i / 10);
			let col = i % 10;
			cell.classList.add("cell");
			cell.dataset.row = row;
			cell.dataset.col = col;

			field.appendChild(cell);
		}

		if (owner === "player") {
			field.classList.add("field", "player");
			Elements.gameArea.playerContField.append(axisX, axisY, field);
		} else if (owner === "computer") {
			field.classList.add("field", "computer");
			Elements.gameArea.enemyContField.append(axisX, axisY, field);
		}
	}

	function renderShipsToPlace() {
		const divShips = document.createElement("div");
		divShips.classList.add("ships");
		divShips.id = "ships";
		divShips.innerHTML = `
      <div class="ship choose" id="carrier" data-length = "5">
          <img src="${carrier}" alt="Carrier">
          <svg xmlns="http://www.w3.org/2000/svg" version="1.1" class="border">
            <defs>
              <filter id="squiggly-0">
                <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="0"/>
                <feDisplacementMap id="displacement" in="SourceGraphic" in2="noise" scale="6" />
              </filter>
              <filter id="squiggly-1">
                <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="1"/>
          <feDisplacementMap in="SourceGraphic" in2="noise" scale="8" />
              </filter>

              <filter id="squiggly-2">
                <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="2"/>
          <feDisplacementMap in="SourceGraphic" in2="noise" scale="6" />
              </filter>
              <filter id="squiggly-3">
                <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="3"/>
          <feDisplacementMap in="SourceGraphic" in2="noise" scale="8" />
              </filter>

              <filter id="squiggly-4">
                <feTurbulence id="turbulence" baseFrequency="0.02" numOctaves="3" result="noise" seed="4"/>
          <feDisplacementMap in="SourceGraphic" in2="noise" scale="6" />
              </filter>
            </defs> 
          </svg>
      </div>
      <div class="ship" id="battleship" data-length="4">
          <img src="${battleship}" alt="Battleship">
      </div>
      <div class="ship" id="destroyer" data-length="3">
          <img src="${destroyer}" alt="Destroyer">
      </div>
      <div class="ship" id="submarine" data-length="3">
          <img src="${submarine}" alt="Submarine">
      </div>
      <div class="ship" id="boat" data-length="2">
          <img src="${boat}" alt="Boat">
      </div>
      `;

		Elements.gameArea.divPlaceShips.lastElementChild.before(divShips);
	}

	function hoverPreview(validStatus, cell) {
		switch (validStatus) {
			case true:
				cell.classList.add("preview-valid");
				break;
			case false:
				cell.classList.add("preview-invalid");
				break;
		}

		lastHoveredCells.push(cell);
	}

	function clearPreview() {
		lastHoveredCells.forEach((cell) =>
			cell.classList.remove("preview-valid", "preview-invalid"),
		);
		lastHoveredCells = [];
	}

	function disablePreview(fieldOwner) {
		const field = document.querySelector(`.field.${fieldOwner}`);
		field.classList.add("disabled");
	}

	function enablePreview(fieldOwner) {
		const field = document.querySelector(`.field.${fieldOwner}`);
		field.classList.remove("disabled");
	}

	function enableBtnStart() {
		Elements.buttons.btnStartBattle.classList.remove("disabled");
	}

	function renderIMGShip(
		row,
		col,
		length,
		axis,
		id,
		field = "player",
		rerender = false,
	) {
		let fieldToAppend;
		let rerenderImg;
		let div = document.querySelector(`.field.${field} .wrapper-ship#${id}`);

		if (div === null) {
			div = document.createElement("div");
			div.classList.add("wrapper-ship");
			div.id = id;
			let img = document.createElement("img");
			img.src = `./img/ship-${id}.png`;
			img.alt = id;

			if (axis === "y") {
				div.style.cssText = `
          grid-column-start: ${col + 1};
          grid-column-end: ${col + 2};
          grid-row-start: ${row + 1};
          grid-row-end: ${row + length + 1};
          max-width: 2rem;
          height: var(--${id}-width);
          `;

				img.style.cssText = `
          width: calc(var(--${id}-width) * 0.9);
          transform: rotate(90deg);
          `;
			} else {
				div.style.cssText = `
            grid-column-start: ${col + 1};
            grid-column-end: ${col + length + 1};
            grid-row-start: ${row + 1};
            grid-row-end: ${row + 2};
            width: var(--${id}-width);
            height: 2rem;
            `;
				img.style.cssText = `width: calc(var(--${id}-width) * 0.9);`;
			}

			// Placement in grid
			div.append(img);

			if (field === "computer") {
				fieldToAppend = document.querySelector(".computer.field");
			} else if (field === "player") {
				fieldToAppend = document.querySelector(".player.field");
			}

			fieldToAppend.appendChild(div);
		}

		if (field === "computer") {
			if (rerender === true) {
				setTimeout(() => {
					div.classList.add("appeared");
				}, 200);
			}
		} else if (field === "player") {
			if (rerender === true) {
				div.firstElementChild.classList.add("disappeared");
				rerenderImg = document.createElement("img");
				rerenderImg.src = `./img/ship-${id}.png`;
				rerenderImg.alt = id;
				rerenderImg.classList.add("rerender");
				setTimeout(() => rerenderImg.classList.add("appeared"), 200);

				if (axis === "y") {
					rerenderImg.style.cssText = `
            width: calc(var(--${id}-width) * 0.9);
            transform: rotate(90deg);
            `;
				} else {
					rerenderImg.style.cssText = `width: calc(var(--${id}-width) * 0.9);`;
				}
				div.append(rerenderImg);
			}
		}
	}

	function updateStatusBar(status, plName) {
		let text = "";

		switch (status) {
			case "start":
				text = "All ships are set, ready to start the battle.";
				break;
			case "computer's turn":
				text = "The enemy is attacking.";
				break;
			case "waiting":
				text = `Waiting for your orders, ${plName}!`;
				break;
			case "invalid":
				text = "This placement is invalid!";
				break;
			case "hitEnemy":
				text = "The enemy hits your ship!";
				break;
			case "sinkEnemy":
				text = "The enemy sinks your ship!";
				break;
			case "hitPlayer":
				text = "You hit the enemy's ship!";
				break;
			case "sinkPlayer":
				text = "You sink the enemy's ship!";
				break;
		}

		Elements.statusBar.textContent = text;
	}

	function renderHit(cell) {
		const crossLine1 = document.createElement("img");
		crossLine1.src =
			"data:image/svg+xml;base64,";
		crossLine1.classList.add("arm", "arm-1");

		const crossLine2 = document.createElement("img");
		crossLine2.src =
			"data:image/svg+xml;base64,";
		crossLine2.classList.add("arm", "arm-2");

		const div = document.createElement("div");
		div.classList.add("cross", "playing");

		cell.classList.add("hit");
		cell.appendChild(div);
		div.appendChild(crossLine1);
		div.appendChild(crossLine2);
	}

	function renderMiss(cell) {
		const div = document.createElement("div");
		div.classList.add("circle");

		div.innerHTML = `
        <svg
           width="20.877mm"
           height="20.597mm"
           viewBox="-2 -2 20.877 20.597"
           version="1.1"
           xmlns="http://www.w3.org/2000/svg">
          <defs>
            <filter id="hand-drawn" x="-40%" y="-40%" width="180%" height="180%">
              <feTurbulence type="fractalNoise" baseFrequency="0.09" numOctaves="2" seed="3" result="noiseA" />
              <feDisplacementMap in="SourceGraphic" in2="noiseA" scale="2.5" result="wobbledA" />
              <feTurbulence type="fractalNoise" baseFrequency="0.07" numOctaves="2" seed="11" result="noiseB" />
              <feDisplacementMap in="SourceGraphic" in2="noiseB" scale="2.5" result="wobbledB" />
              <feMorphology in="wobbledB" operator="dilate" radius="0.6" result="thickB" />
              <feMerge>
                <feMergeNode in="thickB" />
                <feMergeNode in="wobbledA" />
              </feMerge>
            </filter>
          </defs>
          <g transform="translate(-1.0979011,-1.5995736)">
            <path
               filter="url(#hand-drawn)"
               pathLength="1"
               style="fill:none; stroke:#232376; stroke-width:1.5; stroke-linecap:round; stroke-linejoin:round; stroke-dasharray:1; stroke-dashoffset:1; animation: draw-in 0.6s ease-out forwards;"
               d="m 30.418213,12.302098 c 0.747442,2.074324 0.633353,4.879862 -0.933183,6.484392 -1.67201,1.712564 -3.767194,2.715792 -5.539265,2.917389 -3.544144,0.403193 -7.348018,-2.537291 -7.65345,-6.697257 -0.305433,-4.159965 1.881521,-8.9399099 6.241256,-9.3536944 2.253436,-0.2138746 4.92541,0.6919048 6.800971,2.1537203 2.085218,1.6252227 3.017621,6.0832001 2.713317,8.8168751"
               transform="rotate(-90,14.969148,19.113834)" />
          </g>
        </svg>
      `;

		cell.appendChild(div);
	}

	function renderSink(firstCell, length, axis, id, field) {
		const row = firstCell[0];
		const col = firstCell[1];

		renderIMGShip(row, col, length, axis, id, field, true);
		let cells = [];
		if (axis === "x") {
			for (let cell = firstCell[1]; cell < firstCell[1] + length; cell++) {
				cells.push(findCell({ row: row, col: cell }, field));
			}
		} else if (axis === "y") {
			for (let cell = firstCell[0]; cell < firstCell[0] + length; cell++) {
				cells.push(findCell({ row: cell, col: col }, field));
			}
		}

		cells.forEach((cell) => {
			cell.classList.remove("hit");
			cell.classList.add("sunk");
		});
	}

	function renderWin(winner) {
		const div = document.createElement("dialog");
		let text;

		if (winner === "player") {
			text = "You have sunken all the enemy's ships. You won!";
		} else if (winner === "computer") {
			text = "The enemy has sunken all your ships... The enemy won!";
		}

		div.classList.add("win-notif");
		div.id = "win-notif";
		div.innerHTML = `
        <p>${text}</p>
        <button type="button" class="btn-again">Play again</button>
      `;

		Elements.gameArea.div.appendChild(div);
		div.showModal();
	}

	function rerenderNewGame() {
		const enemyFieldChildren = document.querySelectorAll(
			".container-field.computer > :not(:first-child)",
		);
		const playerFieldChildren = document.querySelectorAll(
			".container-field.player > :not(:first-child)",
		);

		enemyFieldChildren.forEach((el) => el.remove());
		playerFieldChildren.forEach((el) => el.remove());
		Elements.buttons.btnStartBattle.classList.add("disabled");

		Elements.gameArea.div.classList.add("hidden");
		Elements.gameArea.divPlaceShips.classList.remove("hidden");
		Elements.gameArea.enemyContField.classList.add("hidden");
		Elements.statusBar.classList.add("hidden");
		Elements.btnRestart.classList.add("hidden");
		Elements.newGame.div.classList.remove("hidden");
	}

	return {
		renderSVGborder,
		renderAxis,
		renderField,
		renderShipsToPlace,
		hoverPreview,
		clearPreview,
		disablePreview,
		enablePreview,
		enableBtnStart,
		renderIMGShip,
		updateStatusBar,
		renderHit,
		renderMiss,
		renderSink,
		renderWin,
		rerenderNewGame,
	};
})();
